"""Layer 15 MLP down-projection, component 4163: a "subject-then-verb" detector.

It fires on the verb slot of a clause: a finite auxiliary or copula (is, are, was,
were, will, would, can, may, has, does, seems, ...) that comes straight after a
clause subject. Its strength depends on what the subject is:

- a noun subject ("Abstracting with credit is", "the results were"): strongest;
- a pronoun subject ("it is", "this is", "there is"): medium;
- a personal pronoun ("we are", "you can", "they have"): near zero;
- a wh-word or "if" before it ("what is", "if it is"): slightly negative.

Subject pronouns that open a new clause (after a comma or a clause-linking word
such as "but", "and", "that", "which", "then") get a medium-positive value, and so
does an adverb that sits between an auxiliary and its predicate ("is also",
"are generally"). Pronouns after a wh-word or "if" get a small negative value.
Everything else is 0. Activations are signed and have a diffuse part on ordinary
tokens (commas, "the", digits) that these rules do not model: the program captures
the large, clause-structural cases only.
"""

import re

from wordnet import parts_of_speech

READS = ()

# Finite auxiliaries and copulas, and linking verbs that behave like them.
AUX = {"is", "are", "was", "were", "will", "would", "can", "may", "has", "have",
       "does", "did", "should", "could", "might", "must", "shall", "had",
       "seems", "seem", "seemed", "looks", "look", "remains", "remain", "feels",
       "feel", "sounds", "become", "becomes", "became"}
BE = {"be", "been", "being"}
PERSONAL = {"i", "you", "he", "she", "we", "they", "me", "him", "her", "us", "them"}
PRONOUN_SUBJECT = {"it", "this", "that", "there", "which", "one"}
WH = {"what", "how", "why", "where", "who", "when", "whether", "if"}
CLAUSE_START = {",", "but", "and", "that", "which", "then", "so", "because", "since",
                ":", "or", "maybe", "perhaps", "think", "sure", "?"}
ADVERB = {"also", "not", "often", "usually", "generally", "really", "always",
          "still", "very", "probably", "actually", "just"}
FUNCTION = {"the", "a", "an", "of", "to", "in", "on", "for", "with", "at", "by",
            "from", "and", "or", "but", "so", "as", "than", "no"}


def is_noun(word):
    """A plain English word that WordNet lists as a noun, and is not a function word."""
    if not re.fullmatch(r"[a-z]+", word) or word in FUNCTION | PERSONAL | PRONOUN_SUBJECT | WH:
        return False
    return "noun" in parts_of_speech(word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_document = (len(prefix.document_ids) > 1
                     and prefix.document_ids[-2] == prefix.document_ids[-1])
    prev = prefix.token_strings[-2].strip().lower() if same_document else ""

    if word in AUX:
        if prev in PERSONAL:
            value = 0.3
        elif prev in PRONOUN_SUBJECT:
            value = 1.6
        elif prev in WH:
            value = -0.2
        elif is_noun(prev):
            value = 2.9
        else:
            value = 2.2
    elif word in BE:
        value = 1.3
    elif word in PERSONAL or word in PRONOUN_SUBJECT:
        if prev in CLAUSE_START:
            value = 2.0
        elif prev in WH:
            value = -0.3
        else:
            value = 0.6
    elif word in ADVERB:
        value = 1.5 if prev in AUX else 0.2
    else:
        value = 0.0
    return carry, float(value)

"""Predicate-verb detector for layers.15 mlp.down_proj, component 4165.

The component is positive on the word that carries a clause's predicate. Its
strongest positives are auxiliaries and copulas (is, was, been, has), strongest
right after a noun subject ("success is") and weaker after a pronoun ("it is").
Modals (will, can, should) and tensed verbs (takes, made, showed) are high too,
as are bare verbs right after a modal or "to"; -ing forms and bare infinitives
are lower. Colons, verb contractions ('m, 've, n't) and the Japanese subject
particles が and は are positive as well. It is negative on adverbs and
connectives (therefore, thus, -ly words) and on prepositions and function words
(of, a, that, or, so). Nouns, most punctuation and everything else sit near 0.
"""
from wordnet import base_forms, parts_of_speech

READS = ()

COPULA = {"is", "was", "are", "were", "be", "been", "being", "am", "has", "have", "had"}
MODAL = {"will", "would", "can", "may", "must", "should", "could", "might", "shall"}
DEICTIC = {"it", "this", "that", "what", "here", "there", "which", "these", "those"}
PERSONAL = {"we", "you", "i", "they", "he", "she", "who"}
CLITIC = {"'m", "'ve", "'re", "'ll", "n't", ",n't"}
PARTICLE = {"が", "は"}
CONNECTIVE = {"therefore", "thus", "hence", "however", "consequently", "accordingly", "otherwise", "moreover", "furthermore"}
FUNCTION = {"of", "a", "an", "that", "or", "so", "to", "in", "on", "for", "with", "from", "by", "as", "than"}


def _verb_value(word, prev):
    """A verb's value: bare after a modal or 'to' high, tensed forms high, -ing and bare lower."""
    if prev in MODAL or prev == "to":
        return 1.1
    if word.endswith("ing"):
        return 0.6
    lemmas = base_forms(word)
    if lemmas and lemmas[0] != word:
        return 0.9
    return 0.35


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in COPULA:
        if prev in DEICTIC:
            return carry, 0.9
        if prev in PERSONAL:
            return carry, 1.4
        return carry, 2.1
    if word in MODAL:
        return carry, 1.2
    if word in CLITIC:
        return carry, 0.9
    if word in PARTICLE:
        return carry, 2.0
    if raw.strip().endswith(":"):
        return carry, 1.1
    if word.isalpha() and word.isascii():
        pos = parts_of_speech(word)
        if "verb" in pos:
            return carry, _verb_value(word, prev)
        if word in CONNECTIVE or ("adverb" in pos and word.endswith("ly")):
            return carry, -0.8
    if word in FUNCTION:
        return carry, -0.2
    return carry, 0.05

"""Slot-opening tokens: the component goes negative where a label, value, example or
definition is about to be written, and sits near zero elsewhere."""
READS = ()

# Punctuation that opens a value: colons and equals signs, arrows, dashes and pipes.
MARKS = {":", "：", ":\n", ":\n\n", ":\n\n\n", '":', "):", "=", " =", ")=", " —", " |", " ->", " →", " ≈"}
# Words that introduce an example, a definition or a predicate.
INTRO = {" is", " are", " be", " was", " as", " like", " such", " including", " include", " called", " named", " example", " namely", " born"}
# Prepositions that lead into a noun phrase.
PREP = {" of", " to", " at", " by", " from", " with", " in", " on", " between", " for", " about", " using"}
# Nouns that name a field whose value follows (e.g. "time zone", "exit code", "arguments").
FIELDS = {" entity", " zone", " directory", " citizenship", "arguments", "command", " occupation", " name", " country", " exit", " birth", " instance", " located", " team", " death", " working", " path"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in MARKS:
        value = -2.5
    elif cur in FIELDS:
        value = -2.2
    elif cur in INTRO:
        value = -1.1
    elif cur in PREP:
        value = -0.45
    else:
        value = -0.17
    if prev in FIELDS:
        value -= 2.0
    return carry, value

"""Layer 15, MLP down_proj component 4178: a "wrap-up" detector.

The component reads mostly MLP hidden unit 4178 of layer 15 (41% of its input weight), and its
activation tracks that unit (r about 0.54). Its output promotes words such as "conclude",
"Conclusion" and "thank", and its activation rises where a text starts to wrap up, or where one
paragraph or section ends and the next begins. Most of its variance is in the context around a
token, which a program over single tokens cannot see, so this program captures only part of it.

Rules, added together per token:
  - a wrap-up word ("Finally", "Lastly", "Overall", "Conclusion", "Ultimately", "Summary",
    "concludes") adds 3;
  - a connective that often opens a new point ("Therefore", "Thus", "Hence", "Furthermore",
    "Further", "Meanwhile", "Anyway", "Now") adds 1.2;
  - the end of a paragraph or section (a sentence-final mark, optionally followed by a closing
    quote or bracket, then a newline; or a markdown heading or divider) adds 1.3;
  - any other token containing a newline adds 0.2, and a sentence end without one 0.15;
  - the first token after a paragraph or section break adds 0.8;
  - everything else is 0.
"""
import re

READS = ()

WRAP_UP = {"Finally", "Lastly", "Overall", "Conclusion", "Ultimately", "Summary", "concludes", "conclude", "CLUSION"}
CONNECTIVES = {"Therefore", "Thus", "Hence", "Furthermore", "Further", "Meanwhile", "Anyway", "Now"}
PARAGRAPH_END = re.compile(r".*[.。!\]][\"”)]?\n+")
HEADING = re.compile(r"#{2,}|={3,}")
SENTENCE_END = re.compile(r".*[.!?。！？]")


def is_break(piece):
    return bool(PARAGRAPH_END.fullmatch(piece) or HEADING.fullmatch(piece))


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    word = piece.strip()
    value = 0.0
    if word in WRAP_UP:
        value += 3.0
    elif word in CONNECTIVES:
        value += 1.2
    if is_break(piece):
        value += 1.3
    elif "\n" in piece:
        value += 0.2
    elif SENTENCE_END.fullmatch(piece):
        value += 0.15
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc and is_break(prefix.token_strings[-2]):
        value += 0.8
    return carry, value

"""Component layers.15.mlp.down_proj:4181 goes negative on opening brackets in running text.

What it does, read off its activations:
- An opening parenthesis " (" or "（" (or "(" with no space, at a weaker 0.3 scale) is
  strongly negative, most of all early in a document and when it follows a capitalised
  name ("Mary Lee (born 1..."). The value fades over the first ~100 tokens of a document.
- A plain square bracket " [" or "[" is weakly negative.
- The word "by" is mildly negative; "see", "e.g.", "i.e.", "such", "including" are mildly
  positive.
- A document's first token, and every other token, predicts 0.

This is a sketch: it explains only a few percent of the component's variance. Most of the
variance is small, token-independent noise that no token or position rule captures.
"""
import re

READS = ()

PARENS = {" (", "(", "（"}
BRACKETS = {" [", "["}
BY = {" by", " By"}
EXAMPLE_WORDS = {"see", ".g", ".e", "such", "including"}
CAPITALISED_WORD = re.compile(r"[A-Z][a-z]+")


def step(carry, prefix, upstream):
    # carry = (document label of the last token, its position within that document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n = 0
    else:
        n = carry[1] + 1
    carry = (doc, n)
    tok = prefix.token_strings[-1]
    if n == 0:
        return carry, 0.0
    if tok in BY:
        return carry, -0.8
    if tok in EXAMPLE_WORDS:
        return carry, 1.2
    if tok in BRACKETS:
        return carry, -0.3
    if tok not in PARENS:
        return carry, 0.0
    # an opening parenthesis: strongest early in the document and after a capitalised name
    prev = prefix.token_strings[-2].strip()
    if CAPITALISED_WORD.fullmatch(prev):
        value = -4.0 if n < 20 else (-3.3 if n < 100 else -2.4)
    else:
        value = -3.0 if n < 20 else (-1.3 if n < 100 else -0.8)
    if tok == "(":
        value *= 0.3
    return carry, value

"""Layer 15, MLP hidden unit 4185 (the down_proj component 4185, which reads this unit).

What it does: the unit goes negative where the text is on, or about to reach, an act of
understanding or appreciating, and where a bare verb such as "understand" is the expected
next word. Its activation is strongest on "understand" / "understanding" and similar words,
and on "to" (or the object pronoun before it) after cues like "help you", "allows you",
"able", "ability", "how", "what", "ready". Softer negatives sit on knowledge and ability
words and on "can" / "will". Everywhere else it is small and noisy, so the program predicts
a constant there.

Only the current token and a few tokens before it are read. No state is carried.
"""

# Words of understanding and appreciation: the unit's strongest negative cases.
UNDERSTAND = {
    "understand", "understanding", "understood", "comprehend", "grasp",
    "appreciate", "appreciation", "interpret",
}
# Softer knowledge and ability words.
KNOWLEDGE = {
    "knowledge", "aware", "informed", "inform", "skills", "skill", "capable",
    "learn", "know", "educate", "recognize",
}
# Cues after which a verb of ability or purpose is likely to follow.
ENABLE = {
    "help", "helps", "allow", "allows", "enable", "enables", "prepare", "prepared",
    "able", "ability", "needed", "how", "what", "which", "ready", "qualifies", "qualify",
    "fitted", "fit", "serve", "equip", "empower", "lets", "let",
}
OBJECTS = {"you", "me", "him", "her", "us", "them"}
MODALS = {"can", "will"}
BASELINE = -0.035  # the unit's typical value

READS = ()


def step(carry, prefix, upstream):
    words = [t.strip().lower() for t in prefix.token_strings[-4:]]
    word = words[-1]
    before = words[-2] if len(words) > 1 else ""
    enable_nearby = any(w in ENABLE for w in words[-4:-1])
    if word in UNDERSTAND:
        value = -2.0
    elif word == "better":
        value = -0.7
    elif word in KNOWLEDGE:
        value = -0.5
    elif word == "to" and before in ENABLE:
        value = -0.9
    elif word in OBJECTS and enable_nearby:
        value = -0.7
    elif word in MODALS:
        value = -0.2
    else:
        value = BASELINE
    return carry, value

"""Layer 15 MLP down_proj, component 4197: separators inside open code brackets.

What it does, in plain terms: it is near zero on most text, and rises on the
punctuation of source code that sits inside an open bracket. The strongest case is
a comma that separates arguments of a function call still open at that point, e.g.
`f(a, b, [[,]] c` (about 3 on average, often 10-25). Other cases:
  - a comma inside any other open bracket (list, dict, tuple): about 1.5;
  - a colon anywhere: about 1.3;
  - an indentation token inside a call's argument list: about 0.9 (0.4 in other brackets);
  - the tag word `param` (as in `@param` doc comments): about 7;
  - a quote character inside a bracket: about 0.5.
Identifiers, digits and plain prose stay near zero.

The program tracks, through the document, the stack of brackets still open. A `(`
that directly follows an identifier (`f(`) opens a call; every other opening bracket
(`(` after an operator, `[`, `{`) opens a grouping. Each token's prediction is a
fixed value for its kind of token, times the kind of innermost open bracket. The
stack is reset where the document changes, as the model does.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

OPEN = "([{"
CLOSE = ")]}"

# Predicted activation by token kind and by the innermost open bracket
# ("call": inside a function call's parentheses; "group": any other open bracket;
# "none": no open bracket).
VALUE = {
    "comma": {"call": 3.1, "group": 1.5, "none": 0.0},
    "colon": {"call": 1.3, "group": 1.3, "none": 1.3},
    "indent": {"call": 0.9, "group": 0.4, "none": 0.0},
    "param": {"call": 6.9, "group": 6.9, "none": 6.9},
    "quote": {"call": 0.5, "group": 0.5, "none": 0.0},
}


def _kind(text: str) -> str | None:
    """The kind of a token's text, or None if no kind applies."""
    if text.strip() == "param":
        return "param"
    if "," in text:
        return "comma"
    if ":" in text:
        return "colon"
    if text and not text.strip():
        return "indent"
    if '"' in text or "'" in text:
        return "quote"
    return None


def step(carry, prefix, upstream: Mapping):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "stack": [], "last": " "}
    stack, last = carry["stack"], carry["last"]
    # Update the bracket stack with this token's characters, in order.
    for ch in prefix.token_strings[-1]:
        if ch in OPEN:
            is_call = ch == "(" and (last.isalnum() or last == "_")
            stack.append("call" if is_call else "group")
        elif ch in CLOSE and stack:
            stack.pop()
        if not ch.isspace():
            last = ch
    carry = {"doc": doc, "stack": stack, "last": last}
    kind = _kind(text)
    if kind is None:
        return carry, 0.0
    context = stack[-1] if stack else "none"
    if kind == "quote" and context == "none":
        return carry, 0.0
    return carry, float(VALUE[kind][context])

"""Layer 15 MLP hidden unit 4198, read through its down_proj component.

What the component is: a rank-one piece of layers.15.mlp.down_proj. Its activation is
(hidden . v) * |u|, and its direction v is dominated by MLP hidden unit 4198 of layer 15
(about 40% of v's energy). So the activation is, mostly, a scaled copy of that one
hidden unit: a diffuse, roughly Gaussian signal with spread 0.33, mostly within +-1,
with rare spikes to -8 (e.g. the "." of a list item "1 ." or a "the" in a title).

What this program does: it predicts the component's activation from the newest token
alone, using a few word classes whose average activation differs from the rest:
  - chat-template markers (<|im_start|>, <|endoftext|>): clearly negative;
  - sentence-opening pronouns and auxiliaries (I, you, it, can, have, let): negative;
  - digits and indentation/whitespace runs: mildly negative;
  - newlines: mildly positive;
  - everything else: a small negative offset (the component's mean).
The class means are averages over 8192 training rows, rounded.

Honest limit: these classes explain only about 0.3% of the variance on held-out rows.
Token identity overall (a full unigram table) explains about 2%, and neighbouring tokens,
document position or repetition add little more. The signal is spread across many
contexts, so there is no short surface rule that captures it; this program is a
summary of the averages, not an account of what unit 4198 computes.
"""

READS = ()

CHAT_MARKERS = {"<|im_start|>", "<|im_end|>", "<|endoftext|>"}
PRONOUNS_AUX = {" I", " you", " You", " It", " can", " have", " has", " Let"}
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in CHAT_MARKERS:
        value = -0.11
    elif s in PRONOUNS_AUX:
        value = -0.11
    elif s in DIGITS:
        value = -0.05
    elif "\n" in s:
        value = 0.04
    elif s.strip() == "":
        value = -0.05
    else:
        value = -0.01
    return carry, float(value)

"""Layer 15 MLP unit 4200 (down_proj component 4200): a code-structure detector.

It runs high on tokens that open or close a declaration in source code (access modifiers,
`void`, `def`, `function`, `param`, `@` annotations, the end of a doc comment `*/`),
and on the indentation that starts the body line after a signature. It runs low on
mid-expression tokens such as `=` and member access `.name`. Everywhere else it sits
near its resting value.
"""
READS = ()

DECL_WORDS = {"public", "private", "protected", "static", "void", "function", "def", "class",
              "param", "returns", "label", "func", "export", "template"}
SIGNATURE_WORDS = ("public", "private", "protected", "static", "void", "function", "def",
                   "class", "func", "export", "int", "string", "bool", "fn")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "line": "", "prev": ""}
    line, prev = carry["line"], carry["prev"]
    line_before = line
    word = token.strip()
    if "\n" in token:
        pieces = (line + token).split("\n")
        for piece in pieces[:-1]:
            if piece.strip():
                prev = piece
        line = pieces[-1]
    else:
        line += token
    value = -0.04
    if "*/" in token or "///" in token:
        value = 1.3
    elif word in DECL_WORDS:
        value = 0.65
    elif word.startswith("@"):
        value = 0.8
    elif "{" in token:
        value = 0.15
    elif word == "" and line_before == "" and ")" in prev and prev.lstrip().startswith(SIGNATURE_WORDS) and not prev.rstrip().endswith((";", "{")):
        value = 0.85
    elif "=" in token or word.startswith("."):
        value = -0.13
    carry = {"doc": doc, "line": line, "prev": prev}
    return carry, value

"""Clause-boundary punctuation and transition words.

Component p-82af68dd@100000/layers.15.mlp.down_proj:4205 responds mostly to punctuation
that marks a clause boundary. It is strongest on the comma that closes an opening phrase
("However," "Then," "I think," "In the end,"), where a new clause is about to start.
It is weak on commas inside numbers or code, and negative on transition words themselves
("however", "therefore", "thus", "hmm", "wait").

- a comma right after a transition word is strongly positive;
- a comma after a word is positive, more so the closer it is to the start of its sentence;
- a comma at the end of a line is mildly positive;
- a comma after a digit or a symbol ("1,000", "f(x),") is weak;
- colons and semicolons, which introduce an explanation or a list, are mildly positive;
- a transition word is negative: strongly for "however"/"therefore"/"thus"-type words,
  weakly for "also"/"then"/"so"-type words.

Everything else is 0. Sentences are tracked causally from the tokens so far, and the
sentence state resets at each sentence end and at each document boundary.
"""

import re

READS = ()

COMMAS = {",", "，", "、"}
COLONS = {":", "：", ";", "；"}
STRONG = {
    "thus", "therefore", "hence", "however", "moreover", "furthermore", "additionally",
    "consequently", "nevertheless", "alternatively", "instead", "indeed", "otherwise",
    "hmm", "wait", "meanwhile",
}
WEAK = {
    "also", "then", "now", "first", "finally", "next", "still", "yet", "after", "here",
    "example", "addition", "fact", "well", "but", "so",
}
TRANSITIONS = STRONG | WEAK
SENTENCE_END = (".", "!", "?", "\n")
# a word of two or more letters, or one kana, kanji or hangul character
WORD = re.compile(r"[^\W\d_]{2,}|[぀-ヿ㐀-鿿가-힯]")

COMMA_AFTER_TRANSITION = 2.9
COMMA_AFTER_WORD = (2.4, 2.0, 1.4, 1.1)  # by words since sentence start: 1-2, 3-4, 5-8, more
COMMA_AFTER_SYMBOL = 0.5  # after a digit or symbol, as in 1,000
COMMA_AT_LINE_END = 0.4
COLON_VALUE = 0.7
STRONG_VALUE = -1.0
WEAK_VALUE = -0.4


def step(carry, prefix, upstream):
    # carry: (tokens so far in this sentence, the previous token's word), or None
    new_document = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_document:
        carry = (0, "")
    n_words, last_word = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if word[:1] in COMMAS:
        if "\n" in token:
            value = COMMA_AT_LINE_END
        elif last_word in TRANSITIONS:
            value = COMMA_AFTER_TRANSITION
        elif WORD.fullmatch(previous):
            distance = 0 if n_words <= 2 else 1 if n_words <= 4 else 2 if n_words <= 8 else 3
            value = COMMA_AFTER_WORD[distance]
        else:
            value = COMMA_AFTER_SYMBOL
    elif word[:1] in COLONS:
        value = COLON_VALUE
    elif word in STRONG:
        value = STRONG_VALUE
    elif word in WEAK:
        value = WEAK_VALUE
    # update the sentence state with this token
    if any(mark in token for mark in SENTENCE_END):
        carry = (0, "")
    else:
        carry = (n_words + 1, word)
    return carry, value

"""Layer 15 MLP hidden unit 4215 (its down_proj component 4215), predicted from the
last two words.

What it responds to: connectives that open an alternative or a comparison. " or" and
" than" push it up most (mean about +0.8, with a wide spread). " but" and " by" push it
up a little (about +0.25). After a pronoun ("you or", "me and", "him,") the links are
stronger: " or" goes to about +2, and a comma or " and" goes to about +0.6. Determiners
and quantifiers that start a noun phrase (" the", " any", " no", " one", " other",
" their", ...) push it slightly negative, and " of" more so (about -0.25). Every other
position is predicted as 0. These word rules explain only about 1 to 2 percent of the
activation: most of its variance depends on the surrounding text, which this does not
model.
"""

READS = ()

PRONOUNS = {" you", " me", " him", " us", " them", " her", " it", " I", " he", " she", " we", " they", " people"}
ALTERNATIVE = {" or": 0.8, " than": 0.7}
LINKS = {" but": 0.3, " by": 0.25}
DETERMINERS = {
    " the", " a", " an", " this", " these", " those", " that", " all", " any", " no",
    " one", " other", " their", " his", " her", " your", " our", " my", " its", " every",
    " each", " some", " many", " more", " most", " such",
}


def level(prev, word):
    after_pronoun = prev in PRONOUNS
    if word == " or" and after_pronoun:
        return 2.0
    if word in ALTERNATIVE:
        return ALTERNATIVE[word]
    if word in LINKS:
        return LINKS[word]
    if word in (",", " and") and after_pronoun:
        return 0.6
    if word == " of":
        return -0.25
    if word in DETERMINERS:
        return -0.12
    return 0.0


def step(carry, prefix, upstream):
    words = prefix.token_strings
    prev = words[-2] if len(words) > 1 else ""
    return carry, level(prev, words[-1])
